import { existsSync, readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { defineConfig } from "vite";

// The reference pages in api/ are generated by apps/api-docs (`pnpm --filter @voxxy/api-docs build`), which
// the landing's build waits for. Without them the site still builds, just without the reference.
const apiDir = new URL("api/", import.meta.url);
const apiPages = existsSync(apiDir) ? readdirSync(apiDir).filter((f) => f.endsWith(".html")).map((f) => `api/${f}`) : [];

// The library's version, shown on the page as %VOXXY_VERSION% (the reference pages read the same file).
const { version } = JSON.parse(readFileSync(new URL("../../packages/voxxy/package.json", import.meta.url), "utf8")) as { version: string };

export default defineConfig({
  plugins: [{ name: "voxxy-version", transformIndexHtml: (html) => html.replaceAll("%VOXXY_VERSION%", version) }],
  appType: "mpa",
  base: "./",
  worker: { format: "es" },
  build: {
    rollupOptions: {
      input: ["index.html", "examples/speak.html", "examples/transcribe.html", ...apiPages].map((file) =>
        fileURLToPath(new URL(file, import.meta.url)),
      ),
    },
  },
});
